WHERE 1 = 1

AND w.work_order_no LIKE concat('%', #{query.workOrderNo}, '%')
AND w.equipment_id = #{query.equipmentId}
AND w.status = #{query.status}
AND w.fault_category = #{query.faultCategory}
AND w.priority = #{query.priority}
AND w.reporter_id = #{query.reporterId}
AND w.handler_id = #{query.handlerId}
AND (r.nick_name LIKE concat('%',#{query.reporterName},'%') OR r.user_name LIKE concat('%',#{query.reporterName},'%'))
AND (h.nick_name LIKE concat('%',#{query.handlerName},'%') OR h.user_name LIKE concat('%',#{query.handlerName},'%'))
AND w.create_time >= #{query.beginTime}
AND w.create_time < #{query.endTime}
AND w.status IN ('WAITING','PROCESSING','PENDING_REVIEW')
ORDER BY w.create_time DESC, w.work_order_id DESC

mapper.update:
UPDATE eq_work_order SET handler_id=#{handlerId},status=#{status},assigned_time=#{assignedTime},
    version=version+1,update_by=#{updateBy},update_time=#{updateTime}
WHERE work_order_id=#{workOrderId} AND version=#{version} AND status='WAITING'

UPDATE eq_work_order SET status=#{status},cancelled_time=#{cancelledTime},
    version=version+1,update_by=#{updateBy},update_time=#{updateTime}
WHERE work_order_id=#{workOrderId} AND version=#{version} AND status='WAITING'

UPDATE eq_work_order SET status=#{order.status},last_submit_time=#{order.lastSubmitTime},
    closed_time=#{order.closedTime},version=version+1,
    update_by=#{order.updateBy},update_time=#{order.updateTime}
WHERE work_order_id=#{order.workOrderId} AND version=#{order.version} AND status=#{fromStatus}
AND handler_id=#{handlerId}
